class Box<T> {
    private T value;
    Box(T value) { this.value = value; }
    T get() { return value; }
    <R> Box<R> map(java.util.function.Function<T, R> fn) { return new Box<>(fn.apply(value)); }
}

Box<String> b = new Box<>("java");
Box<Integer> len = b.map(String::length);
System.out.println(len.get());

