public class Main {
    record Pair<A, B>(A first, B second) {}

    static <T extends Comparable<T>> T max(T a, T b) {
        return a.compareTo(b) >= 0 ? a : b;
    }

    public static void main(String[] args) {
        Pair<String, Integer> p = new Pair<>("age", 21);
        System.out.println(p.first() + "=" + p.second());
        System.out.println(max(3, 9));
        System.out.println(max("apple", "mango"));
    }
}

import java.util.*;

public class Main {
    static double total(List<? extends Number> values) {
        double sum = 0;
        for (Number n : values) sum += n.doubleValue();
        return sum;
    }

    public static void main(String[] args) {
        System.out.println(total(List.of(1, 2, 3)));
        System.out.println(total(List.of(1.5, 2.5)));
        Integer a = 127, b = 127, c = 1000, d = 1000;
        System.out.println(a == b);
        System.out.println(c == d);
        System.out.println(c.equals(d));
        Integer missing = null;
        try {
            int x = missing;
            System.out.println(x);
        } catch (NullPointerException e) {
            System.out.println("unboxing null failed");
        }
    }
}

